const express = require('express');
const router = express.Router();
const { Connection, Client } = require('@temporalio/client');
const { db } = require('../db');

router.get('/api/jobs/tax-calculation/:workflowId/result', verifyUserToken, async (req, res) => {
  const { workflowId } = req.params;

  const job = await db.query(
    'SELECT id FROM user_tax_jobs WHERE workflow_id = $1 AND user_id = $2',
    [workflowId, req.user.id]
  );
  if (job.rowCount === 0) {
    return res.status(403).json({ error: 'Access denied to workflow results' });
  }

  const connection = await Connection.connect({ address: process.env.TEMPORAL_ADDRESS });
  const client = new Client({ connection });

  const handle = client.workflow.getHandle(workflowId);
  const result = await handle.result();

  return res.json({ workflowId, output: result });
});
